#!/usr/bin/env bash
# setup-convex.sh — generate GrowMate's Convex backend env, then fetch its admin key.
#
# Usage:
#   bash deploy/setup-convex.sh           # pre-start: create data/convex/.env
#   bash deploy/setup-convex.sh --post    # post-start: write data/convex/admin-key
#
# The admin key is generated by the backend container and is required by the
# Convex CLI for function deploys and deployment env changes.
set -euo pipefail

source "$(cd "$(dirname "$0")" && pwd)/lib.sh"

OUT="$DATA_DIR/convex/.env"
ADMIN_KEY="$DATA_DIR/convex/admin-key"

if [ "${1:-}" = "--post" ]; then
	if [ -e "$ADMIN_KEY" ]; then
		keep_existing "$ADMIN_KEY"
	else
		if ! run_as_podman podman inspect services-convex-1 >/dev/null 2>&1; then
			die "services-convex-1 is not running; start the stack first"
		fi
		if ! key="$(run_as_podman podman exec services-convex-1 ./generate_admin_key.sh 2>/dev/null | grep '|' | tail -n 1)"; then
			die "could not generate the Convex admin key"
		fi
		[ -n "$key" ] || die "could not generate the Convex admin key"
		tmp="$(mktemp)"
		trap 'rm -f "$tmp"' EXIT
		printf '%s\n' "$key" >"$tmp"
		install_file "$tmp" "$ADMIN_KEY" 600
		echo "wrote $ADMIN_KEY (600, contains credentials; never commit)"
	fi

	GROW_ENV="$DATA_DIR/growmate/.env"
	if [ -f "$GROW_ENV" ]; then
		access="$(env_value "$GROW_ENV" RUSTFS_ACCESS_KEY)"
		secret="$(env_value "$GROW_ENV" RUSTFS_SECRET_KEY)"
		cat <<EOF

Next, set the function env and deploy from the growmate app repo:

  cd ~/projects/apps/growmate
  export CONVEX_SELF_HOSTED_URL=https://convex.growmate.bond
  export CONVEX_SELF_HOSTED_ADMIN_KEY="\$(cat $ADMIN_KEY)"
  bunx convex env set RUSTFS_ENDPOINT http://rustfs:9000
  bunx convex env set RUSTFS_ACCESS_KEY $access
  bunx convex env set RUSTFS_SECRET_KEY $secret
  bunx convex env set RUSTFS_BUCKET_IMAGE images
  bunx convex deploy --yes

EOF
	else
		echo
		echo "See services/growmate/convex.env.example for the function env to set."
	fi
	exit 0
fi

if [ -e "$OUT" ]; then
	keep_existing "$OUT"
	exit 0
fi

need_cmd openssl
RUSTFS_ENV="$DATA_DIR/rustfs/.env"
[ -f "$RUSTFS_ENV" ] || die "missing $RUSTFS_ENV; run deploy/setup-rustfs.sh first"
ACCESS="$(env_value "$RUSTFS_ENV" RUSTFS_ACCESS_KEY)"
SECRET="$(env_value "$RUSTFS_ENV" RUSTFS_SECRET_KEY)"
[ -n "$ACCESS" ] && [ -n "$SECRET" ] || die "missing RustFS credentials in $RUSTFS_ENV"

INSTANCE_SECRET="${INSTANCE_SECRET:-$(new_hex 32)}"
ADMIN_PASSWORD="${ADMIN_PASSWORD:-$(new_hex 12)}"

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
sed -e "s|{{CONVEX_INSTANCE_SECRET}}|$INSTANCE_SECRET|g" \
	-e "s|{{CONVEX_ADMIN_PASSWORD}}|$ADMIN_PASSWORD|g" \
	-e "s|{{RUSTFS_ACCESS_KEY}}|$ACCESS|g" \
	-e "s|{{RUSTFS_SECRET_KEY}}|$SECRET|g" \
	"$REPO_DIR/services/env/convex.env.example" >"$tmp"
if grep -q '{{' "$tmp"; then
	die "unrendered placeholder in services/env/convex.env.example"
fi

install_file "$tmp" "$OUT" 600

echo
echo "wrote $OUT (600, contains credentials; never commit)"
echo "  INSTANCE_SECRET  : $INSTANCE_SECRET"
echo "  Admin email      : admin@growmate.bond"
echo "  Admin password   : $ADMIN_PASSWORD"
echo
echo "next: start the stack, then run: bash deploy/setup-convex.sh --post"
